	"golive__tip_broadcaster_1": "<b>TIP:</b> Thanks for going live! Welcome people by saying “hi” to them when they join your video.",
	"golive__tip_broadcaster_10": "<b>TIP:</b> Thank you for going live on X! <3",
	"golive__tip_broadcaster_2": "<b>TIP:</b> Try mentioning people by name when they join your live video — they’ll be thrilled!",
	"golive__tip_broadcaster_3": "<b>TIP:</b> Be sure to go live for at least a few minutes to make it easier for people to find you.",
	"golive__tip_broadcaster_4": "<b>TIP:</b> Ask your viewers where they’re from — it’s a great way to break the ice.",
	"golive__tip_broadcaster_5": "<b>TIP:</b> Thank people for tuning in and respond to their comments to keep them watching.",
	"golive__tip_broadcaster_6": "<b>TIP:</b> If you lose your connection while going live, go somewhere with a better signal.",
	"golive__tip_broadcaster_7": "<b>TIP:</b> Ask people to follow you so they can get notified the next time you go live.",
	"golive__tip_broadcaster_8": "<b>TIP:</b> Start your live video by saying “hi” right away. People watching afterwards will love it.",
	"golive__tip_broadcaster_9": "<b>TIP:</b> Thank people for watching before you end your live video.",
	"golive__tip_pre_broadcast_1": "<b>TIP:</b> Write a title before you go live to help people discover your video.",
	"golive__tip_pre_broadcast_2": "<b>TIP:</b> A descriptive title helps people better understand what your live video is about.",
	"golive__tip_pre_broadcast_3": "<b>TIP:</b> Need ideas? Give a tour, share a talent, or talk about something that interests you.",
	"golive__tip_pre_broadcast_4": "<b>TIP:</b> Make sure you have a strong phone signal before going live.",
	"golive__tip_pre_broadcast_5": "<b>TIP:</b> Add a hashtag to your title to help people discover your live video.",
	"golive__tip_pre_broadcast_6": "<b>TIP:</b> That’s all the tips we have for now — thanks for going live on X!",
