	"ps__tip_broadcaster_1": "<b>TIP:</b> Thanks for broadcasting! Be sure to say hi to people when they join.",
	"ps__tip_broadcaster_11": "<b>TIP:</b> Thank you for broadcasting on Periscope! <3",
	"ps__tip_broadcaster_2": "\"<b>TIP:</b> Try calling out viewers who join by name; they'll be thrilled!\"",
	"ps__tip_broadcaster_3": "<b>TIP:</b> Be sure to broadcast for at least a few minutes to make it easier for people to find you.",
	"ps__tip_broadcaster_4": "\"<b>TIP:</b> Asking your viewers where they're from is a great way to break the ice.\"",
	"ps__tip_broadcaster_5": "<b>TIP:</b> Thank viewers for tuning in and respond to their comments to keep them engaged.",
	"ps__tip_broadcaster_6": "<b>TIP:</b> If you lose connection while broadcasting, go somewhere with better signal.",
	"ps__tip_broadcaster_7": "<b>TIP:</b> Ask your viewers to follow you so they can get notified when you go live.",
	"ps__tip_broadcaster_8": "<b>TIP:</b> Start your broadcast by saying hi right away. Your replay viewers will love it.",
	"ps__tip_broadcaster_9": "<b>TIP:</b> Thank your viewers for watching before you end your broadcast.",
	"ps__tip_pre_broadcast_1": "<b>TIP:</b> Write a title before you start your broadcast and meet people with similar interests!",
	"ps__tip_pre_broadcast_2": "<b>TIP:</b> A descriptive title helps people understand what your broadcast is about.",
	"ps__tip_pre_broadcast_3": "<b>TIP:</b> Need ideas? Give a tour, share a talent, or talk about a topic that interests you.",
	"ps__tip_pre_broadcast_4": "<b>TIP:</b> Make sure you have a strong phone signal before going live.",
	"ps__tip_pre_broadcast_5": "<b>TIP:</b> Share your broadcasts on X to reach more viewers.",
	"ps__tip_pre_broadcast_6": "<b>TIP:</b> If you follow people that follow you back, you can broadcast privately to them.",
	"ps__tip_pre_broadcast_8": "<b>TIP:</b> Add a relevant hashtag to your title to help people discover your broadcast.",
	"ps__tip_pre_broadcast_9": "\"<b>TIP:</b> That's all the tips we have for now, thanks for using Periscope!\"",
	"ps__tip_viewer_1": "\"<b>TIP:</b> You're one of the first to join, write a comment and say hi!\"",
	"ps__tip_viewer_2": "\"<b>TIP:</b> Write a comment and let <b>%1$s</b> know you're here!\"",
	"ps__tip_viewer_3": "\"<b>TIP:</b> Let <b>%1$s</b> know where you're watching from!\"",
